# Extracts constant tables from the Rails application into generated Go
# source, so the Go port reads exactly the data the Rails code declares.
#
#   cd $RAILS_ROOT && bin/rails runner $GO_ROOT/tools/gen/tables.rb $GO_ROOT
#
# The output files carry a "Code generated" header and must not be edited.
require "json"

GO_ROOT = ARGV.fetch(0)

def go_string(s)
  s.to_s.to_json.gsub("\\u003c", "<").gsub("\\u003e", ">").gsub("\\u0026", "&")
end

def write(path, package, body)
  full = File.join(GO_ROOT, path)
  File.write(full, <<~GO)
    // Code generated by tools/gen/tables.rb from the Rails application; DO NOT EDIT.

    package #{package}

    #{body}
  GO
  puts "wrote #{path}"
end

# I18n default transliteration approximations.
approx = I18n::Backend::Transliterator::HashTransliterator::DEFAULT_APPROXIMATIONS
write("internal/rb/translit_table.go", "rb", <<~GO)
  var transliterations = map[rune]string{
  #{approx.map { |k, v| "\t#{k.ord}: #{go_string(v)}," }.join("\n")}
  }
GO

# Bible::BookCatalog::BOOKS in declaration order.
books = Bible::BookCatalog::BOOKS
write("internal/bible/books_table.go", "bible", <<~GO)
  // bookPairs are Bible::BookCatalog::BOOKS in declaration order.
  var bookPairs = []bookPair{
  #{books.map { |k, v| "\t{#{go_string(k)}, #{v}}," }.join("\n")}
  }

  // booksByID is Bible::BookCatalog::BOOKS_BY_ID.
  var booksByID = map[int]string{
  #{Bible::BookCatalog::BOOKS_BY_ID.map { |k, v| "\t#{k}: #{go_string(v)}," }.join("\n")}
  }
GO

# Liturgical::Translator book names.
def int_string_map(name, hash)
  "var #{name} = map[int]string{\n#{hash.map { |k, v| "\t#{k}: #{go_string(v)}," }.join("\n")}\n}\n"
end
write("internal/liturgical/translator_books_table.go", "liturgical",
  int_string_map("booksEN", Liturgical::Translator::BOOKS_EN_BY_ID) +
  int_string_map("booksES", Liturgical::Translator::BOOKS_ES_BY_ID) +
  int_string_map("booksCY", Liturgical::Translator::BOOKS_CY_BY_ID))
